    operation StatePrep_IsQubitOne (q : Qubit, state : Int) : Unit {
        if state != 0 {
            // convert |0⟩ to |1⟩
            X(q);
        }
    }


    operation T101_IsQubitOne () : Unit {
        DistinguishTwoStates_OneQubit(StatePrep_IsQubitOne, IsQubitOne, ["|0⟩", "|1⟩"]);
    }


